<script setup>
import { onMounted,onBeforeUnmount,ref,watch } from 'vue'
import { Button,Input,Empty } from 'ant-design-vue'
import { documentApi } from './documentApi.js'
import { createTaskPoller,useDocumentRead } from './documentState.js'
import { isTaskRunning } from './documentModel.js'
import ReadState from './ReadState.vue'
import Facts from './Facts.vue'
const props=defineProps({document:Object,initialTaskId:String,initialKind:String});const emit=defineEmits(['finished','strategy'])
const kind=ref(props.initialKind || (String(props.document.latestTaskType)==='2'?'build':'parse')),taskId=ref(props.initialTaskId || (!props.initialKind || props.initialKind===(String(props.document.latestTaskType)==='2'?'build':'parse')?props.document.latestTaskId:'') || '')
const poll=createTaskPoller((body,signal)=>documentApi.read(kind.value,body,signal)),history=useDocumentRead('logs'),historyPage=ref(1)
function read(){history.data.value=null;historyPage.value=1;poll.start({documentId:props.document.documentId,taskId:taskId.value || undefined,logLimit:'60'})}
function changeKind(){poll.pause();poll.data.value=null;history.data.value=null;taskId.value=''}
function readHistory(page=1){historyPage.value=page;history.read({taskId:poll.data.value.taskId,pageNo:String(page),pageSize:'30'})}
watch(()=>poll.data.value,(value,old)=>{if(old&&isTaskRunning(old)&&!isTaskRunning(value))emit('finished')})
onMounted(read);onBeforeUnmount(poll.dispose)
const labels={taskId:'任务 ID',taskTypeName:'任务类型',taskStatusName:'状态',currentStageName:'当前阶段',startTime:'开始时间',finishTime:'结束时间',costMillis:'耗时（ms）',errorCode:'错误码',errorMsg:'错误',parseMode:'解析模式',parserName:'解析器',parserVersion:'版本',pageCount:'页数',blockCount:'块数',tableCount:'表格数',planReady:'策略已就绪',totalLogCount:'日志总数'}
</script>
<template><section class="admin-next-doc-panel"><h2>任务与日志</h2><form class="admin-next-doc-toolbar" @submit.prevent="read"><label for="doc-task-kind" class="chat-next-sr-only">任务类型</label><select id="doc-task-kind" v-model="kind" @change="changeKind"><option value="parse">解析与策略</option><option value="build">索引构建</option></select><label for="doc-task-id" class="chat-next-sr-only">任务 ID</label><Input id="doc-task-id" v-model:value="taskId" placeholder="留空读取最近任务" /><Button html-type="submit" :disabled="poll.loading.value">查看任务</Button><Button v-if="isTaskRunning(poll.data.value)" @click="poll.pause()">暂停自动刷新</Button></form><ReadState :state="poll" label="任务" @retry="read" /><template v-if="poll.data.value"><Facts :value="Object.fromEntries(Object.entries(poll.data.value).filter(([k])=>['taskId','taskTypeName','taskStatusName','currentStageName','startTime','finishTime','costMillis','errorCode','errorMsg','parseMode','parserName','parserVersion','pageCount','blockCount','tableCount','planReady','totalLogCount'].includes(k)))" :labels="labels" /><Button v-if="poll.data.value.planReady" @click="$emit('strategy')">查看策略</Button><h3>增量日志</h3><ol class="admin-next-doc-logs"><li v-for="log in poll.data.value.logs" :key="log.id"><strong>{{ log.stageTypeName || '阶段未记录' }} · {{ log.eventTypeName || log.logLevelName }}</strong><time>{{ log.createTime }}</time><p>{{ log.content }}</p><details v-if="log.detailJson"><summary>日志详情 · {{ log.id }}</summary><pre>{{ log.detailJson }}</pre></details></li></ol><Empty v-if="!poll.data.value.logs?.length" description="暂无增量日志" /><Button v-if="poll.data.value.taskId" @click="readHistory(1)">查看历史日志</Button><ReadState :state="history" label="历史日志" @retry="readHistory(historyPage)" /><div v-if="history.data.value"><Facts :value="history.data.value.logs" /><div class="admin-next-doc-toolbar"><Button :disabled="historyPage<=1||history.loading.value" @click="readHistory(historyPage-1)">上一页日志</Button><span>第 {{ historyPage }} 页 · 共 {{ history.data.value.total ?? '—' }} 条</span><Button :disabled="historyPage*30>=Number(history.data.value.total)||history.loading.value" @click="readHistory(historyPage+1)">下一页日志</Button></div></div></template></section></template>
